package com.unicare.dispensary.message;import java.time.LocalDateTime;import java.util.List;public record MessageResponse(Long id,Long studentId,String studentName,String studentNumber,String subject,String body,MessageStatus status,LocalDateTime createdAt,List<ReplyResponse> replies){static MessageResponse from(DispensaryMessage m){return new MessageResponse(m.getId(),m.getStudent().getId(),m.getStudent().getFullName(),m.getStudent().getStudentNumber(),m.getSubject(),m.getBody(),m.getStatus(),m.getCreatedAt(),m.getReplies().stream().map(r->new ReplyResponse(r.getAuthor(),r.getBody(),r.getCreatedAt())).toList());}public record ReplyResponse(String by,String body,LocalDateTime createdAt){}}
